// تألیفی
#include <stdio.h>

#define CAPACITY 5

int stack[CAPACITY];
int size = 0;

void push(int n)
{
    if (size < CAPACITY)
    {
        stack[size] = n;
        size++;
    }
}

int pop(void)
{
    size--;
    return stack[size];
}

int main(void)
{
    push(1);
    push(2);
    push(3);
    printf("%i\n", pop());
    push(4);
    printf("%i\n", pop());
    printf("%i\n", pop());
    return 0;
}
